package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoansForStatsPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoansForStatsPort loadLoansForStatsPort;

    public GetMonthlyStatsService(LoadLoansForStatsPort loadLoansForStatsPort) {
        this.loadLoansForStatsPort = loadLoansForStatsPort;
    }

    @Override
    public MonthlyStatsView getMonthlyStats(MonthlyStatsQuery query) {
        YearMonth month = YearMonth.of(query.year(), query.month());
        LocalDate from = month.atDay(1);
        LocalDate to = month.atEndOfMonth();

        List<Loan> loaned = loadLoansForStatsPort.loadLoansLoanedBetween(from, to);
        List<Loan> returned = loadLoansForStatsPort.loadLoansReturnedBetween(from, to);

        // 연체료는 도메인 규칙(주말 기한 등)으로 계산한다. 여기서 다시 계산하지 않는다.
        long overdueCount = returned.stream().filter(loan -> loan.lateFee() > 0).count();
        long lateFeeTotal = returned.stream().mapToLong(Loan::lateFee).sum();
        return new MonthlyStatsView(query.year(), query.month(), loaned.size(), returned.size(),
                overdueCount, lateFeeTotal);
    }
}
