        borrowAndReturn(memberId, "2030-06-03", "2030-06-10");
        // 2030-05 대출 C: 기한 06-03, 06-05 반납 -> 2일 연체, 200원 (반납은 6월, 대출은 5월)
        borrowAndReturn(memberId, "2030-05-20", "2030-06-05");
        // 2030-06 대출 D: 아직 반납 안 함
        borrow(memberId, "2030-06-25");

        mockMvc.perform(get("/stats/monthly").param("year", "2030").param("month", "6"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2030))
                .andExpect(jsonPath("$.month").value(6))
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(3))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(500));
    }

    @Test
    void month_without_activity_is_all_zero() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2030").param("month", "7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void invalid_month_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2030").param("month", "13"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void missing_year_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("month", "6"))
                .andExpect(status().isBadRequest());
    }

    private void borrowAndReturn(String memberId, String loanedAt, String returnedAt) throws Exception {
        String loanId = borrow(memberId, loanedAt);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String borrow(String memberId, String loanedAt) throws Exception {
        String bookId = registerBook();
        String body = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of(
                                "bookId", bookId, "memberId", memberId, "loanedAt", loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"통계테스트\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook() throws Exception {
        String body = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Stats " + java.util.UUID.randomUUID() + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }
}
